This Terraform configuration creates an AWS S3 Glacier Vault and integrates it with Amazon SNS notifications. It provisions:

- An AWS Glacier Vault
- An SNS topic to receive Glacier notifications
- An SNS topic policy allowing the Glacier service to publish messages
- Glacier vault notification configuration for archive retrieval and inventory retrieval completion events

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Glacier vault and SNS topic will be created."
  type        = string
  default     = "us-east-1"
}

variable "glacier_vault_name" {
  description = "Name of the S3 Glacier vault."
  type        = string
  default     = "example-glacier-vault-with-sns"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic for Glacier vault notifications."
  type        = string
  default     = "example-glacier-vault-notifications"
}

data "aws_caller_identity" "current" {}

resource "aws_sns_topic" "glacier_notifications" {
  name = var.sns_topic_name
}
